// Entity scope belongs to Admin; optional participant filters belong to templates.
const entityFilterFields=[{id:'type',name:'User Type'},{id:'center',name:'Center'},{id:'city',name:'City'},{id:'state',name:'State'},{id:'id',name:'Entity ID'},{id:'name',name:'Name'}];
const centerData=[{id:'BLR-HSR',city:'Bangalore',state:'Karnataka'},{id:'BLR-WF',city:'Bangalore',state:'Karnataka'},{id:'FM-BLR',city:'Bangalore',state:'Karnataka'}];
function entityValue(u,key){if(['city','state'].includes(key))return centerData.find(c=>c.id===u.center)?.[key];return u[key]}
function matchesEntity(t,u){const tests=(t.entityFilters||[]).map(f=>compare(entityValue(u,f.key),f.op,f.value));return !tests.length||(t.entityFilterJoin==='OR'?tests.some(Boolean):tests.every(Boolean));}
// Preserve eligibility of existing examples while moving it to the Manager layer.
if(!state.entityFilterMigration){for(const t of state.templates){const s=structure(t.structure);t.entityFilters||=[];if(s?.userType&&s.userType!=='All')t.entityFilters.push({key:'type',op:'IN',value:s.userType});}state.entityFilterMigration=true;}
for(const s of state.structures)s.userType='All';
const policyStructureForm=structureForm;
structureForm=function(){draft.userType='All';policyStructureForm();const d=$('#editor');d.innerHTML=d.innerHTML.replace(/<label>User Type<select[\s\S]*?<\/select><\/label>/g,'');};
const policyComponent=componentForm;
componentForm=function(c,i){return policyComponent(c,i).replace(/<label>Value type<select[\s\S]*?<\/select><\/label>/g,'').replace(/<label>Effect/g,'<label>Operator');};
structureView=function(){return title('Payout structures','Fixed · Unit-based',btn('+ Create structure','new-structure','',true))+`<div class="panel">${table(['Structure','Type','Entity','Evaluation','Status',''],current(state.structures).map(s=>row([esc(s.name),[...new Set(s.components.map(payoutType))].map(esc).join(' · '),esc(s.entity),s.period,`<span class="pill ${s.status==='Live'?'live':''}">${s.status}</span>`,`<div class="actions">${btn('Open','edit-structure',s.id)}${btn('Duplicate','duplicate-structure',s.id)}</div>`])))}</div>`};
function entityFilterForm(){draft.entityFilters||=[];return `<section class="panel"><div class="panel-head"><h3>Entity filters <span class="quiet">Optional</span></h3><button data-policy="add-filter">+ Add filter</button></div><div class="panel-body">${!draft.entityFilters.length?'<p class="quiet">Applies to all entities in the selected Business Line and Entity.</p>':`${select('Combine conditions','entityFilterJoin',['AND','OR'],draft.entityFilterJoin||'AND')}${draft.entityFilters.map((f,i)=>`<div class="grid3 section-gap">${select('Field',`entityFilters.${i}.key`,entityFilterFields,f.key)}${select('Operator',`entityFilters.${i}.op`,['IN','NOT IN'],f.op)}${input('Values (comma-separated)',`entityFilters.${i}.value`,f.value)}<button data-policy="remove-filter" data-index="${i}">Remove</button></div>`).join('')}`}</div></section>`}
const policyTemplateForm=templateForm;
templateForm=function(){policyTemplateForm();if(draft.structure){const d=$('#editor');d.innerHTML=d.innerHTML.replace('<div id="form-error"',entityFilterForm()+'<div id="form-error"');}};
const policyCalculate=calculate;
calculate=function(t,u){if(!matchesEntity(t,u))throw Error('Entity does not match this template’s filters.');return policyCalculate(t,u)};
const policyAssignments=assignmentsForUser;
assignmentsForUser=function(u){return policyAssignments(u).filter(a=>matchesEntity(template(a.template),u))};
const policyAssign=assign;
assign=function(a){const t=template(a.template);if(t&&a.kind==='User'){const u=users.find(u=>u.id===a.target);if(u&&!matchesEntity(t,u))throw Error('Selected entity does not match the template filters.');}if(t&&a.kind==='Center'&&!users.some(u=>u.center===a.target&&matchesEntity(t,u)&&u.lob===structure(t.structure).lob&&u.entity===structure(t.structure).entity))throw Error('No sample entities in this center match the template filters.');return policyAssign(a)};
const policyLoadTemplate=loadTemplateStructure;
loadTemplateStructure=function(id){draft.entityFilters=[];draft.entityFilterJoin='AND';policyLoadTemplate(id)};
const rateEvents=[{id:'added',name:'New entity added to a center',choices:['center']},{id:'transferred',name:'Entity transferred to a center',choices:['retain','center']},{id:'reactivated',name:'Entity reactivated at a center',choices:['retain','center']},{id:'changed',name:'Template changed on a center',choices:['retain','center']},{id:'new-center',name:'New center added',choices:['nearest']}];
const rateActionNames={retain:'Entity retains the previous rate',center:'Entity gets the center’s rate',nearest:'Center gets the rate of the nearest matching center'};
state.rateEvents||=[];
function rulesForContext(){for(const e of rateEvents)if(!state.rateEvents.some(r=>r.event===e.id&&r.lob===lob&&r.entity===entity))state.rateEvents.push({id:uid(),event:e.id,lob,entity,action:e.choices[0],enabled:false});return state.rateEvents.filter(r=>r.lob===lob&&r.entity===entity)}
triggerView=function(){return title('Trigger logics','Choose how rates change for each event.')+`<div class="notice">Sample configuration · Events do not run automatically. “Try example” previews the rate source.</div><div class="panel">${table(['Event','Action','Status',''],rulesForContext().map(r=>row([esc(rateEvents.find(e=>e.id===r.event).name),esc(rateActionNames[r.action]),`<span class="pill ${r.enabled?'live':''}">${r.enabled?'Enabled':'Disabled'}</span>`,`<div class="actions"><button data-policy="edit-event" data-id="${r.id}">Configure</button><button data-policy="try-event" data-id="${r.id}">Try example</button></div>`])))}</div>`};
function editRateEvent(id){editorType='rate-event';draft=clone(state.rateEvents.find(r=>r.id===id));const e=rateEvents.find(e=>e.id===draft.event);modal(e.name,`${select('Action','action',e.choices.map(id=>({id,name:rateActionNames[id]})),draft.action)}${draft.event==='new-center'?'<div class="notice">Match the city first, then the state. If several centers match, the nearest cannot be determined from city/state alone; a source center must be selected.</div>':''}<label class="section-gap"><input type="checkbox" data-k="enabled" ${draft.enabled?'checked':''}>Enabled</label><p class="quiet">${esc(draft.lob)} / ${esc(draft.entity)}</p>`,`<button class="primary" data-policy="save-event">Save rule</button>`)}
function matchingCenters(city,stateName){const withRates=centerData.filter(c=>state.assignments.some(a=>a.kind==='Center'&&a.target===c.id&&currentTemplates().some(t=>t.id===a.template)));const sameCity=withRates.filter(c=>c.city.toLowerCase()===city.trim().toLowerCase()&&c.state.toLowerCase()===stateName.trim().toLowerCase());return sameCity.length?sameCity:withRates.filter(c=>c.state.toLowerCase()===stateName.trim().toLowerCase())}
function rateSource(action,previous,center){if(action==='retain')return previous?{template:previous,reason:'Previous template and its rate values are retained.'}:{error:'No previous rate is available. No fallback is selected.'};return center?{template:center,reason:'Use the destination center’s template.'}:{error:'The destination center has no template for this structure.'};}
function tryRateEvent(id){editorType='rate-event-preview';const r=state.rateEvents.find(r=>r.id===id);draft={rule:id,sampleUser:entityUsers()[0]?.id||'',destination:entityUsers()[0]?.center||'',previous:'',centerTemplate:'',city:'Bangalore',stateName:'Karnataka',source:''};rateEventPreview()}
function rateEventPreview(){const r=state.rateEvents.find(r=>r.id===draft.rule),e=rateEvents.find(e=>e.id===r.event);const list=currentTemplates();let body=`<p><strong>${esc(rateActionNames[r.action])}</strong></p>${!r.enabled?'<p class="quiet">Disabled rule · preview only.</p>':''}`;if(r.event==='new-center'){const candidates=matchingCenters(draft.city,draft.stateName);if(!candidates.some(c=>c.id===draft.source))draft.source=candidates.length===1?candidates[0].id:'';body+=`<div class="grid">${input('New center city','city',draft.city)}${input('New center state','stateName',draft.stateName)}</div><button class="section-gap" data-policy="refresh-preview">Find matching centers</button>${candidates.length?select('Source center','source',[{id:'',name:'Select matching center'},...candidates.map(c=>({id:c.id,name:c.id+' · '+c.city+', '+c.state}))],draft.source):'<div class="notice">No matching center with an assigned template.</div>'}${candidates.length>1?'<p class="quiet">Multiple matches. City/state does not provide physical distance; select the source center.</p>':''}<div class="notice">${draft.source?'Rate source: '+esc(draft.source):'No rate source selected.'}</div>`;}else{body+=`<div class="grid">${select('Sample entity','sampleUser',entityUsers().map(u=>({id:u.id,name:u.name+' · '+u.id})),draft.sampleUser)}${select(r.event==='changed'?'Center':'Destination center','destination',[...new Set(entityUsers().map(u=>u.center))],draft.destination)}</div><div class="grid section-gap">${r.event!=='added'?select('Previous template','previous',[{id:'',name:'No previous rate'},...list],draft.previous):''}${select(r.event==='changed'?'New center template':'Center template','centerTemplate',[{id:'',name:'No center rate'},...list],draft.centerTemplate)}</div><button class="section-gap" data-policy="refresh-preview">Preview result</button>`;const result=rateSource(r.action,draft.previous,draft.centerTemplate),u=users.find(u=>u.id===draft.sampleUser),t=template(result.template);if(draft.previous&&draft.centerTemplate&&template(draft.previous)?.structure!==template(draft.centerTemplate)?.structure)result.error='Choose previous and center templates for the same payout structure.';if(t&&u&&!matchesEntity(t,u))result.error='Selected template filters do not match this sample entity.';body+=`<div class="notice ${result.error?'warn':''}">${result.error?esc(result.error):`Applied template: <strong>${esc(t?.name)}</strong><br>${esc(result.reason)}`}</div>`;}body+='<p class="quiet">Preview only. No assignments or rate values are changed.</p>';modal(e.name,body)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-policy]');if(!b)return;try{switch(b.dataset.policy){case 'add-filter':draft.entityFilters||=[];draft.entityFilters.push({key:'type',op:'IN',value:''});templateForm();break;case 'remove-filter':draft.entityFilters.splice(Number(b.dataset.index),1);templateForm();break;case 'edit-event':editRateEvent(b.dataset.id);break;case 'try-event':tryRateEvent(b.dataset.id);break;case 'save-event':if(!rateEvents.find(e=>e.id===draft.event).choices.includes(draft.action))throw Error('Select an available action.');saveRecord(state.rateEvents,draft);finish('Trigger rule saved.');break;case 'refresh-preview':rateEventPreview();break;}}catch(error){fail(error.message)}});
// Validate the optional template filters before the existing save handler.
document.addEventListener('click',e=>{if(!e.target.closest('[data-action="save-template"]'))return;try{for(const f of draft.entityFilters||[]){if(!entityFilterFields.some(k=>k.id===f.key)||!['IN','NOT IN'].includes(f.op)||!String(f.value).trim())throw Error('Complete or remove the empty entity filter.');}}catch(error){e.preventDefault();e.stopImmediatePropagation();fail(error.message)}},true);
render();save();

document.addEventListener('change',e=>{if(editorType==='rate-event-preview'&&['source','sampleUser','destination','previous','centerTemplate'].includes(e.target.dataset.k))rateEventPreview();});
